- (void)configureInitialSummary {
    self.selectedTargetBundleIdentifiers = [NSSet set];
    self.environmentState = PXHomeEnvironmentStateNeedsGeneration;
    self.environmentModel = PXLocalizedString(@"image.summary.not_configured");
    self.environmentNetwork = PXLocalizedString(@"image.summary.not_configured");
    self.environmentCarrier = PXLocalizedString(@"image.summary.not_configured");
    self.environmentRegion = PXLocalizedString(@"image.summary.derived_after_carrier");
    self.environmentLocation = PXLocalizedString(@"image.summary.not_configured");
}

- (void)refreshEnvironmentSummary {
    IdentifierManager *identifierManager = [IdentifierManager sharedManager];
    NSMutableSet<NSString *> *selectedBundleIdentifiers = [NSMutableSet set];
    for (NSString *bundleIdentifier in [identifierManager getApplicationInfo:nil]) {
        if ([identifierManager isApplicationInScope:bundleIdentifier]) {
            [selectedBundleIdentifiers addObject:bundleIdentifier];
        }
    }
    self.selectedTargetBundleIdentifiers = [selectedBundleIdentifiers copy];
    self.selectedTargetCount = self.selectedTargetBundleIdentifiers.count;

    NSError *summaryError = nil;
    NSDictionary<NSString *, id> *pendingModel = [self
        resolvedEnvironmentModelWithDidMigrate:nil
        error:&summaryError];
    NSSet<NSNumber *> *pendingNetworks =
        [self.environmentPolicyStore selectedNetworkTypesWithError:&summaryError];
    NSDictionary<NSString *, id> *pendingLocation =
        [self.environmentPolicyStore configuredLocationWithError:&summaryError];
    BOOL pendingLocationWasCleared =
        [self.environmentPolicyStore locationWasExplicitlyClearedWithError:&summaryError];
    self.hasPendingChanges =
        [self.environmentPolicyStore hasPendingChangesWithError:&summaryError];
    NSString *lastAppliedGenerationID =
        [self.environmentPolicyStore lastAppliedGenerationIDWithError:&summaryError];

    PXProfileStore *profileStore = [[PXProfileStore alloc]
        initWithIdentityDirectory:[identifierManager profileIdentityPath]];
    PXProfileManifest *activeManifest = [profileStore activeManifestWithError:nil];
    NSString *modelName = [pendingModel[@"name"] isKindOfClass:[NSString class]]
        ? pendingModel[@"name"]
        : activeManifest.device[@"name"];
    self.environmentModel = modelName.length > 0
        ? modelName
        : PXLocalizedString(@"image.summary.not_configured");

    NSSet<NSNumber *> *displayedNetworks = pendingNetworks;
    if (displayedNetworks.count == 0 && !pendingModel) {
        NSMutableSet<NSNumber *> *activeNetworks = [NSMutableSet set];
        NSArray *identifiers = [activeManifest.network[@"configuredNetworkTypes"] isKindOfClass:NSArray.class]
            ? activeManifest.network[@"configuredNetworkTypes"]
            : @[activeManifest.network[@"configuredNetworkType"] ?: @""];
        for (id identifier in identifiers) {
            PXEnvironmentNetworkType type = [identifier isKindOfClass:NSString.class]
                ? PXEnvironmentNetworkTypeFromIdentifier(identifier)
                : PXEnvironmentNetworkTypeUnspecified;
            if (type != PXEnvironmentNetworkTypeUnspecified) [activeNetworks addObject:@(type)];
        }
        displayedNetworks = [activeNetworks copy];
    }
    self.environmentNetwork = [self localizedNetworkTypes:displayedNetworks];

    NSDictionary<NSString *, id> *carrier = [self selectedCarrierRecordForIdentityDirectory:
        [identifierManager profileIdentityPath]];
    NSString *carrierName = [carrier[@"name"] isKindOfClass:[NSString class]]
        ? carrier[@"name"]
        : activeManifest.network[@"carrierName"];
    self.environmentCarrier = carrierName.length > 0
        ? carrierName
        : PXLocalizedString(@"image.summary.not_configured");
    PXRegionIdentity *region = carrier
        ? PXRegionIdentityForCountryCode(carrier[@"isoCountryCode"],
            [carrier[@"carrierID"] dataUsingEncoding:NSUTF8StringEncoding])
        : nil;
    NSString *regionCountry = [carrier[@"country"] isKindOfClass:[NSString class]]
        ? carrier[@"country"]
        : activeManifest.region[@"countryCode"];
    NSString *timeZone = region.timeZoneIdentifier ?: activeManifest.region[@"timeZone"];
    self.environmentRegion = regionCountry.length > 0 && timeZone.length > 0
        ? PXLocalizedFormat(@"image.settings.region.summary", regionCountry, timeZone)
        : PXLocalizedString(@"image.summary.derived_after_carrier");

    NSString *locationSummary = [pendingLocation[@"address"] isKindOfClass:[NSString class]]
        ? pendingLocation[@"address"]
        : (pendingLocationWasCleared ? nil : activeManifest.location[@"address"]);
    self.environmentLocation = locationSummary.length > 0
        ? locationSummary
        : PXLocalizedString(@"image.summary.not_configured");

    if (summaryError || ![self.environmentOperations isServiceReady]) {
        self.environmentState = PXHomeEnvironmentStateServiceUnavailable;
    } else if (self.lastFailureReport) {
        self.environmentState = PXHomeEnvironmentStatePartialFailure;
    } else if (self.environmentState != PXHomeEnvironmentStateProcessing) {
        NSSet<NSString *> *activeTargetBundleIdentifiers =
            [NSSet setWithArray:activeManifest.appIdentities.allKeys ?: @[]];
        self.environmentState = PXEnvironmentAppliedStateIsReady(
            self.hasPendingChanges,
            lastAppliedGenerationID,
            activeManifest.generationID,
            self.selectedTargetBundleIdentifiers,
            activeTargetBundleIdentifiers)
            ? PXHomeEnvironmentStateReady
            : PXHomeEnvironmentStateNeedsGeneration;
    }
    [self.tableView reloadData];
}

- (nullable NSDictionary<NSString *, id> *)selectedCarrierRecordForIdentityDirectory:(NSString *)identityDirectory {
    if (identityDirectory.length == 0) return nil;
    PXTrustedCarrierPolicyStore *store = [[PXTrustedCarrierPolicyStore alloc] init];
    NSString *carrierID = [store selectedCarrierIDWithError:nil];
    for (NSDictionary<NSString *, id> *carrier in PXCarrierCatalog()) {
        if ([carrier[@"carrierID"] isEqualToString:carrierID]) {
            return carrier;
        }
    }
    return nil;
}

- (NSString *)localizedNetworkType:(PXEnvironmentNetworkType)networkType {
    switch (networkType) {
        case PXEnvironmentNetworkTypeWiFi: return PXLocalizedString(@"image.network.wifi");
        case PXEnvironmentNetworkType5GNR: return PXLocalizedString(@"image.network.5g");
        case PXEnvironmentNetworkType4GLTE: return PXLocalizedString(@"image.network.4g");
        case PXEnvironmentNetworkType3G: return PXLocalizedString(@"image.network.3g");
        case PXEnvironmentNetworkType2G: return PXLocalizedString(@"image.network.2g");
        case PXEnvironmentNetworkTypeNone: return PXLocalizedString(@"image.network.none");
        case PXEnvironmentNetworkTypeUnspecified: return PXLocalizedString(@"image.summary.not_configured");
    }
}

- (NSString *)localizedNetworkTypes:(NSSet<NSNumber *> *)networkTypes {
    if (networkTypes.count == 0) return PXLocalizedString(@"image.summary.not_configured");
    NSMutableArray<NSString *> *names = [NSMutableArray array];
    for (NSString *identifier in PXEnvironmentNetworkTypeIdentifiers(networkTypes)) {
        [names addObject:[self localizedNetworkType:PXEnvironmentNetworkTypeFromIdentifier(identifier)]];
    }
    return [names componentsJoinedByString:PXLocalizedString(@"image.network.summary.separator")];
}

- (PXHomeSection)homeSectionForTableSection:(NSInteger)tableSection {
    if (!self.hasPendingChanges && tableSection >= PXHomeSectionPendingChanges) {
        return (PXHomeSection)(tableSection + 1);
    }
    return (PXHomeSection)tableSection;
}

- (NSInteger)numberOfSectionsInTableView:(UITableView *)tableView {
    (void)tableView;
    return PXHomeSectionCount - (self.hasPendingChanges ? 0 : 1);
}

- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section {
    (void)tableView;
    PXHomeSection homeSection = [self homeSectionForTableSection:section];
    if (homeSection == PXHomeSectionCurrentEnvironment) { return 5; }
    if (homeSection == PXHomeSectionPrivacyCleanup) { return 3; }
    if (homeSection == PXHomeSectionPhysicalDevice) { return 1; }
    return 1;
}

- (NSString *)tableView:(UITableView *)tableView titleForHeaderInSection:(NSInteger)section {
    (void)tableView;
    switch ([self homeSectionForTableSection:section]) {
        case PXHomeSectionTargetApps: return PXLocalizedString(@"image.home.section.target_apps");
        case PXHomeSectionCurrentEnvironment: return PXLocalizedString(@"image.home.section.current_environment");
        case PXHomeSectionPrivacyCleanup: return PXLocalizedString(@"image.home.section.cleanup");
        case PXHomeSectionPhysicalDevice: return PXLocalizedString(@"image.home.device.title");
        default: return nil;
    }
}

- (NSString *)tableView:(UITableView *)tableView titleForFooterInSection:(NSInteger)section {
    (void)tableView;
    if ([self homeSectionForTableSection:section] == PXHomeSectionPrivacyCleanup) {
        return self.cleanupStatusMessage;
    }
    return nil;
}

- (CGFloat)tableView:(UITableView *)tableView heightForHeaderInSection:(NSInteger)section {
    if ([self tableView:tableView numberOfRowsInSection:section] == 0) {
        return CGFLOAT_MIN;
    }
    if ([self tableView:tableView titleForHeaderInSection:section].length == 0) {
        return PXHomeSectionSpacing;
    }
    CGFloat verticalPadding = section == 0
        ? PXHomeFirstSectionHeaderVerticalPadding
        : PXHomeSectionHeaderVerticalPadding;
    return ceil([UIFont preferredFontForTextStyle:UIFontTextStyleFootnote].lineHeight) +
        verticalPadding;
}

- (CGFloat)tableView:(UITableView *)tableView heightForFooterInSection:(NSInteger)section {
    if ([self tableView:tableView numberOfRowsInSection:section] == 0) {
        return CGFLOAT_MIN;
    }
    if ([self homeSectionForTableSection:section] == PXHomeSectionPrivacyCleanup &&
        self.cleanupStatusMessage.length > 0) {
        return UITableViewAutomaticDimension;
    }
    return CGFLOAT_MIN;
}

- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)indexPath {
