    if (section == PXHomeSectionGenerate) { return [self generationCellForTableView:tableView]; }
    if (section == PXHomeSectionPendingChanges) { return [self pendingChangesCellForTableView:tableView]; }
    static NSString *const reuseIdentifier = @"ImageHomeCell";
    UITableViewCell *cell = [tableView dequeueReusableCellWithIdentifier:reuseIdentifier];
    if (!cell) {
        cell = [[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:reuseIdentifier];
        cell.textLabel.adjustsFontForContentSizeCategory = YES;
        cell.detailTextLabel.adjustsFontForContentSizeCategory = YES;
        cell.detailTextLabel.numberOfLines = 2;
    }
    UIListContentConfiguration *content = [UIListContentConfiguration subtitleCellConfiguration];
    cell.selectionStyle = UITableViewCellSelectionStyleDefault;
    cell.accessoryView = nil;
    cell.accessoryType = UITableViewCellAccessoryNone;
    cell.userInteractionEnabled = YES;
    cell.accessibilityTraits = UIAccessibilityTraitButton;
    if (section == PXHomeSectionTargetApps) {
        content.text = PXLocalizedFormat(@"image.home.target_apps.selected", (long)self.selectedTargetCount); content.secondaryText = PXLocalizedString(@"image.home.target_apps.detail"); content.image = [UIImage systemImageNamed:@"app.badge.fill"];
        cell.accessoryType = UITableViewCellAccessoryDisclosureIndicator; cell.accessibilityIdentifier = @"image-home-target-apps";
    } else if (section == PXHomeSectionCurrentEnvironment) {
        [self configureEnvironmentContent:content forRow:indexPath.row];
        cell.accessoryType = indexPath.row == 4 ? UITableViewCellAccessoryDisclosureIndicator : UITableViewCellAccessoryNone;
        cell.selectionStyle = indexPath.row == 4 ? UITableViewCellSelectionStyleDefault : UITableViewCellSelectionStyleNone;
        cell.accessibilityTraits = indexPath.row == 4 ? UIAccessibilityTraitButton : UIAccessibilityTraitStaticText;
        cell.accessibilityIdentifier = [NSString stringWithFormat:@"image-home-environment-%ld", (long)indexPath.row];
    } else if (section == PXHomeSectionPrivacyCleanup) {
        [self configureCleanupContent:content forRow:indexPath.row];
        cell.userInteractionEnabled = !self.cleanupInProgress;
        cell.selectionStyle = self.cleanupInProgress
            ? UITableViewCellSelectionStyleNone
            : UITableViewCellSelectionStyleDefault;
        if (self.cleanupInProgress) {
            content.textProperties.color = UIColor.secondaryLabelColor;
            content.secondaryTextProperties.color = UIColor.tertiaryLabelColor;
            cell.accessibilityTraits |= UIAccessibilityTraitNotEnabled;
        }
        cell.accessibilityIdentifier = [NSString stringWithFormat:@"image-home-cleanup-%ld", (long)indexPath.row];
    } else if (section == PXHomeSectionPhysicalDevice) {
        [self configurePhysicalDeviceContent:content];
        cell.selectionStyle = UITableViewCellSelectionStyleNone;
        cell.accessibilityTraits = UIAccessibilityTraitStaticText;
        cell.accessibilityIdentifier = [NSString stringWithFormat:@"image-home-device-%ld", (long)indexPath.row];
    }
    content.imageProperties.tintColor = UIColor.systemBlueColor;
    content.textProperties.font = [UIFont preferredFontForTextStyle:UIFontTextStyleBody];
    content.secondaryTextProperties.font = [UIFont preferredFontForTextStyle:UIFontTextStyleSubheadline];
    cell.contentConfiguration = content;
    cell.accessibilityLabel = PXLocalizedFormat(@"accessibility.settings.row", content.text, content.secondaryText);
    cell.accessibilityHint = cell.selectionStyle == UITableViewCellSelectionStyleNone ? nil : PXLocalizedString(@"image.home.open_hint");
    return cell;
}

