- (UITableViewCell *)generationCellForTableView:(UITableView *)tableView {
    UITableViewCell *cell = [[UITableViewCell alloc] initWithStyle:UITableViewCellStyleDefault reuseIdentifier:nil];
    UIButton *button = [UIButton buttonWithType:UIButtonTypeSystem];
    button.translatesAutoresizingMaskIntoConstraints = NO;
    BOOL isProcessing = self.environmentState == PXHomeEnvironmentStateProcessing;
    UIButtonConfiguration *configuration = [UIButtonConfiguration filledButtonConfiguration];
    configuration.title = PXLocalizedString(isProcessing
        ? @"image.home.generate.processing_title"
        : @"image.home.generate.title");
