        ? nil
        : [UIImage systemImageNamed:@"arrow.triangle.2.circlepath"];
    configuration.showsActivityIndicator = isProcessing;
    configuration.imagePadding = 8.0; configuration.cornerStyle = UIButtonConfigurationCornerStyleLarge; configuration.baseBackgroundColor = UIColor.systemBlueColor; configuration.baseForegroundColor = UIColor.whiteColor;
    button.configuration = configuration; button.titleLabel.font = [UIFont preferredFontForTextStyle:UIFontTextStyleHeadline]; button.titleLabel.adjustsFontForContentSizeCategory = YES; button.accessibilityIdentifier = @"image-home-generate"; button.accessibilityLabel = PXLocalizedString(@"image.home.generate.accessibility_label"); button.accessibilityHint = PXLocalizedString(@"image.home.generate.accessibility_hint");
    button.accessibilityValue = isProcessing
        ? PXLocalizedString(@"image.home.generate.processing_title")
